    source_url, source_label, retrieved_at, notes)
VALUES
('venue-the-rise-canoe-grounds', 'style_tags', '["rustic", "semi-rural", "boutique farm", "garden ceremony", "custom chapel", "fire pit", "mountain views", "relaxed", "country", "bush backdrop"]'::jsonb, 'known', 0.6, 'directory', 'https://www.theurbanlist.com/sydney/a-list/wedding-venues-sydney', 'Wedlockers/Urban List import 2026-10-15', TIMESTAMPTZ '2026-10-15 00:00:00+00', NULL),
('venue-the-rise-canoe-grounds', 'editorial_summary', '"Small semi-rural farm venue with an outdoor garden, a purpose-built chapel and a fire pit for the evening, framed by mountain views. Rustic and relaxed in feel, with a local bakery as the on-site catering partner."'::jsonb, 'known', 0.6, 'directory', 'https://www.theurbanlist.com/sydney/a-list/wedding-venues-sydney', 'Wedlockers/Urban List import 2026-10-15', TIMESTAMPTZ '2026-10-15 00:00:00+00', NULL),
('venue-art-gallery-of-nsw', 'style_tags', '["cultural", "art-filled", "gallery", "harbour views", "Woolloomooloo views", "next to Botanic Gardens", "city", "elegant", "unique", "seasonal menus"]'::jsonb, 'known', 0.6, 'directory', 'https://www.wedlockers.com.au/b/art-gallery-of-nsw', 'Wedlockers/Urban List import 2026-10-15', TIMESTAMPTZ '2026-10-15 00:00:00+00', NULL),
('venue-art-gallery-of-nsw', 'editorial_summary', '"Wedding receptions among the artworks beside the Botanic Gardens, with rare outlooks over Woolloomooloo and the harbour. Two reception areas suit up to about 250 guests, with seasonal menus from the gallery''s caterer. Hire fees help fund the gallery''s community programs."'::jsonb, 'known', 0.6, 'directory', 'https://www.wedlockers.com.au/b/art-gallery-of-nsw', 'Wedlockers/Urban List import 2026-10-15', TIMESTAMPTZ '2026-10-15 00:00:00+00', NULL),
('venue-art-gallery-of-nsw', 'capacity_seated_max', '116'::jsonb, 'known', 0.6, 'directory', 'https://www.wedlockers.com.au/b/art-gallery-of-nsw', 'Wedlockers/Urban List import 2026-10-15', TIMESTAMPTZ '2026-10-15 00:00:00+00', NULL),
('venue-art-gallery-of-nsw', 'capacity_standing_max', '300'::jsonb, 'known', 0.6, 'directory', 'https://www.wedlockers.com.au/b/art-gallery-of-nsw', 'Wedlockers/Urban List import 2026-10-15', TIMESTAMPTZ '2026-10-15 00:00:00+00', NULL),
('venue-restaurant-hubert', 'style_tags', '["French", "speakeasy", "underground", "vintage", "live jazz", "martinis", "moody", "intimate", "exclusive hire", "CBD", "romantic"]'::jsonb, 'known', 0.6, 'directory', 'https://www.theurbanlist.com/sydney/a-list/wedding-venues-sydney', 'Wedlockers/Urban List import 2026-10-15', TIMESTAMPTZ '2026-10-15 00:00:00+00', NULL),
('venue-restaurant-hubert', 'editorial_summary', '"Candlelit French dining room below street level with a vintage speakeasy mood, live jazz and classic cocktails. Four exclusive-hire spaces, and the whole restaurant can take up to about 200 guests. Suits couples after a moody, glamorous city celebration."'::jsonb, 'known', 0.6, 'directory', 'https://www.theurbanlist.com/sydney/a-list/wedding-venues-sydney', 'Wedlockers/Urban List import 2026-10-15', TIMESTAMPTZ '2026-10-15 00:00:00+00', NULL),
